def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            cells=[(r,c)]; seen.add((r,c))
            for x,y in cells:
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in seen:
                        seen.add((a,b)); cells.append((a,b))
            lo=min(x for x,y in cells); hi=max(x for x,y in cells); left=min(y for x,y in cells); right=max(y for x,y in cells)
            interior=[grid[x][y] for x in range(lo+1,hi) for y in range(left+1,right) if grid[x][y]!=0]
            color=max(set(interior),key=interior.count) if interior else None
            objects.append((cells,color))
    counts={}
    for cells,col in objects:
        if col is not None: counts[col]=counts.get(col,0)+1
    out=[row[:] for row in grid]
    for cells,col in objects:
        if col is not None and counts[col]>1:
            for x,y in cells: out[x][y]=0
    return out

